def migrate_legacy_submissions(apps, schema_editor):
    """Old confirmations were owner submissions, never team acknowledgements."""
    Cart = apps.get_model("song_carts", "SongCart")
    Item = apps.get_model("song_carts", "SongCartItem")
    Email = apps.get_model("song_carts", "SubmissionEmail")
    database = schema_editor.connection.alias
    for cart in Cart.objects.using(database).filter(status="confirmed").iterator():
        # Preserve the known legacy notice outcome without inventing its recipients.
        titles = list(Item.objects.using(database).filter(cart_id=cart.id).values_list(
            "title", flat=True,
        ))
        Email.objects.using(database).create(
            cart_id=cart.id, kind="team_notice", event_key="",
            subject=f"Worship Prep: legacy submission for {cart.service_date}",
            body=f"Legacy song selection for {cart.service_date}:\n" + "\n".join(titles),
            recipients=[], status=cart.notification_status,
            error=cart.notification_error, sent_at=cart.notified_at,
        )
    Cart.objects.using(database).filter(status="confirmed").update(
        status="pending", submitted_at=models.F("confirmed_at"), confirmed_at=None,
    )
    Item.objects.using(database).filter(section="praise_worship").update(section="praise")


def protect_submission_tables(apps, schema_editor):
    """Apply the existing Django-only access boundary to the new tables."""
    if schema_editor.connection.vendor != "postgresql":
        return
    quote = schema_editor.quote_name
    with schema_editor.connection.cursor() as cursor:
        cursor.execute("SELECT current_schema()")
        schema = quote(cursor.fetchone()[0])
        cursor.execute(
            "SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated')"
        )
        roles = ", ".join(quote(row[0]) for row in cursor.fetchall())
        for name in ("CartComment", "SubmissionEmail"):
            model = apps.get_model("song_carts", name)
            table = f"{schema}.{quote(model._meta.db_table)}"
            cursor.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
            if roles:
                cursor.execute(f"REVOKE ALL PRIVILEGES ON TABLE {table} FROM {roles}")
                cursor.execute(
                    f"CREATE POLICY deny_supabase_api ON {table} "
                    f"AS RESTRICTIVE FOR ALL TO {roles} "
                    "USING (false) WITH CHECK (false)"
                )


